// Dependency-free SVG contact sheet: every catalogue type at both LODs, drawn from the exact part lists the renderer receives.
// Review aid only; not imported by the app. Generated by web/tests/asset-catalog.spec.ts with ASSET_CONTACT_SHEET=<path>.
import { getAssetVisual } from "./catalog";
import type { AssetPart, Vec3 } from "./parts";

type M3 = [Vec3, Vec3, Vec3];
const dot = (a: Vec3, b: Vec3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const cross = (a: Vec3, b: Vec3): Vec3 => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const norm = (a: Vec3): Vec3 => { const l = Math.hypot(...a) || 1; return [a[0] / l, a[1] / l, a[2] / l]; };

/** Rotation matrix for three.js Euler order XYZ (R = Rx * Ry * Rz); rows are returned. */
export function eulerXYZ([x, y, z]: Vec3): M3 {
  const [a, b, c, d, e, f] = [Math.cos(x), Math.sin(x), Math.cos(y), Math.sin(y), Math.cos(z), Math.sin(z)];
  return [
    [c * e, -c * f, d],
    [a * f + b * d * e, a * e - b * d * f, -b * c],
    [b * f - a * d * e, b * e + a * d * f, a * c],
  ];
}
export const apply = (m: M3, v: Vec3): Vec3 => [dot(m[0], v), dot(m[1], v), dot(m[2], v)];

/** Physical axis-aligned half extents of a part (metres), after rotation; conservative for cylinders and spheres. */
export function partHalfExtents(p: AssetPart, w: number, d: number): Vec3 {
  const half: Vec3 = [p.scale[0] * w / 2, p.scale[1] / 2, p.scale[2] * d / 2];
  const m = eulerXYZ(p.rotation ?? [0, 0, 0]);
  return [0, 1, 2].map(i => Math.abs(m[i][0]) * half[0] + Math.abs(m[i][1]) * half[1] + Math.abs(m[i][2]) * half[2]) as Vec3;
}

const hex = (c: string): Vec3 => [1, 3, 5].map(i => parseInt(c.slice(i, i + 2), 16)) as Vec3;
const shade = (c: string, k: number) => `rgb(${hex(c).map(v => Math.round(Math.min(255, v * k))).join(",")})`;

const CAMERA: Vec3 = norm([0.62, 0.7, -0.9]);
const FWD: Vec3 = [-CAMERA[0], -CAMERA[1], -CAMERA[2]];
const RIGHT = norm(cross(FWD, [0, 1, 0]));
const UP = cross(RIGHT, FWD);
const LIGHT = norm([0.3, 1, -0.5]);

interface Poly { pts: [number, number][]; fill: string; depth: number }

function partPolys(p: AssetPart, w: number, d: number): Poly[] {
  const m = eulerXYZ(p.rotation ?? [0, 0, 0]);
  const half: Vec3 = [p.scale[0] * w / 2, p.scale[1] / 2, p.scale[2] * d / 2];
  const centre: Vec3 = [p.position[0] * w, p.position[1], p.position[2] * d];
  const world = (l: Vec3): Vec3 => { const r = apply(m, [l[0] * half[0], l[1] * half[1], l[2] * half[2]]); return [r[0] + centre[0], r[1] + centre[1], r[2] + centre[2]]; };
  const proj = (v: Vec3): [number, number] => [dot(v, RIGHT), -dot(v, UP)];
  const depth = dot(centre, FWD);
  if (p.shape === "sphere") {
    const c = proj(centre), r = Math.max(half[0], half[1], half[2]);
    return [{ pts: Array.from({ length: 14 }, (_, i) => [c[0] + Math.cos(i / 14 * 6.2832) * r, c[1] + Math.sin(i / 14 * 6.2832) * r] as [number, number]), fill: shade(p.color, 1.05), depth }];
  }
  const polys: Poly[] = [];
  const face = (corners: Vec3[], normal: Vec3) => {
    const n = apply(m, normal);
    if (dot(n, CAMERA) <= 0) return;
    polys.push({ pts: corners.map(c => proj(world(c))), fill: shade(p.color, 0.55 + 0.5 * Math.max(0, dot(n, LIGHT))), depth: depth + 1e-3 });
  };
  if (p.shape === "box") {
    const s = [-1, 1];
    for (const sign of s) {
      face(s.flatMap(a => s.map(b => [sign, a, b] as Vec3)).sort(order3(0)), [sign, 0, 0]);
      face(s.flatMap(a => s.map(b => [a, sign, b] as Vec3)).sort(order3(1)), [0, sign, 0]);
      face(s.flatMap(a => s.map(b => [a, b, sign] as Vec3)).sort(order3(2)), [0, 0, sign]);
    }
    return polys;
  }
  const N = 12, ring = (y: number) => Array.from({ length: N }, (_, i) => [Math.cos(i / N * 6.2832), y, Math.sin(i / N * 6.2832)] as Vec3);
  for (let i = 0; i < N; i++) {
    const a = i / N * 6.2832, b = (i + 1) / N * 6.2832, mid = (a + b) / 2;
    face([[Math.cos(a), -1, Math.sin(a)], [Math.cos(b), -1, Math.sin(b)], [Math.cos(b), 1, Math.sin(b)], [Math.cos(a), 1, Math.sin(a)]], [Math.cos(mid), 0, Math.sin(mid)]);
  }
  face(ring(1), [0, 1, 0]);
  face(ring(-1), [0, -1, 0]);
  return polys;
}
// Orders the four corners of a face so they form a simple loop.
const order3 = (axis: number) => (a: Vec3, b: Vec3) => {
  const [i, j] = [0, 1, 2].filter(k => k !== axis);
  const ang = (v: Vec3) => Math.atan2(v[j], v[i]);
  return ang(a) - ang(b);
};

export interface SheetItem { type: string; width: number; depth: number }

export function contactSheetSvg(items: SheetItem[], opts: { columns?: number; cell?: number } = {}): string {
  const cols = opts.columns ?? 5, cell = opts.cell ?? 150, pad = 8, labelH = 34;
  const rows = Math.ceil(items.length / cols), cw = cell * 2 + pad * 3, ch = cell + labelH + pad;
  const out: string[] = [`<svg xmlns="http://www.w3.org/2000/svg" width="${cols * cw}" height="${rows * ch}" font-family="system-ui, sans-serif" font-size="10"><rect width="100%" height="100%" fill="#10171c"/>`];
  items.forEach((it, idx) => {
    const ox = (idx % cols) * cw, oy = Math.floor(idx / cols) * ch;
    out.push(`<text x="${ox + pad}" y="${oy + 14}" fill="#e6eef0" font-weight="600">${it.type}</text>`);
    (["overview", "interior"] as const).forEach((lod, k) => {
      const v = getAssetVisual({ type: it.type, footprint: { width_m: it.width, depth_m: it.depth, rotation_deg: 0 } }, lod);
      const polys = v.parts.map(p => ({ p, d: dot([p.position[0] * it.width, p.position[1], p.position[2] * it.depth], FWD) })).sort((a, b) => b.d - a.d).flatMap(({ p }) => partPolys(p, it.width, it.depth));
      const xs = polys.flatMap(q => q.pts.map(pt => pt[0])), ys = polys.flatMap(q => q.pts.map(pt => pt[1]));
      const minX = Math.min(...xs), maxX = Math.max(...xs), minY = Math.min(...ys), maxY = Math.max(...ys);
      const s = (cell - 16) / Math.max(maxX - minX, maxY - minY, 0.01);
      const cx = ox + pad + k * (cell + pad) + cell / 2, cy = oy + labelH + cell / 2;
      out.push(`<rect x="${cx - cell / 2}" y="${cy - cell / 2}" width="${cell}" height="${cell}" fill="#18222a" rx="4"/>`);
      out.push(`<g>${polys.map(q => `<polygon points="${q.pts.map(([x, y]) => `${(cx + (x - (minX + maxX) / 2) * s).toFixed(1)},${(cy + (y - (minY + maxY) / 2) * s).toFixed(1)}`).join(" ")}" fill="${q.fill}" stroke="#0b1014" stroke-width="0.4"/>`).join("")}</g>`);
      out.push(`<text x="${cx - cell / 2 + 4}" y="${cy + cell / 2 - 4}" fill="#8da0a6">${lod} · ${v.parts.length}</text>`);
    });
    out.push(`<text x="${ox + pad}" y="${oy + 28}" fill="#8da0a6">${it.width}×${it.depth} m</text>`);
  });
  out.push("</svg>");
  return out.join("");
}
